        this.health = this.maxHealth;
        this.shield = 0;
        this.shieldMax = 0;
        this.shieldRegen = 0;
        this.maxEnergy = 0;
        this.energy = 0;
        this.energyRegen = 0;
        this.energyIdleDraw = 0;
        this.energyDrainMul = 1;
        this.shotEnergyCost = 4;
        this.lastShotAt = 0;
        this.continuousFireLevel = 0;
        this.chargeEnergyPerSec = 12;
        this.shieldAbsorbEnergyPerDmg = 0.5;
