            this.evasionChance = (this.evasionChance != null ? this.evasionChance : 1) * ev;
            this.evasionSpeed = (this.evasionSpeed || 2) * (0.5 + 0.5 * ev);
            this.evasionCooldown = (this.evasionCooldown || 5000) / Math.max(0.35, ev);
