            p.vx = Math.cos(a) * sp * dir;
            p.vy = Math.sin(a) * sp;
            p.s = Math.random() < 0.7 ? Math.max(1, cell * 0.5) : cell;
            p.c = palette[(Math.random() * palette.length) | 0];
