        const lum = Math.floor(200 + 55 * t);
        const finalR = Math.min(255, Math.floor(lum * schemeRgb.r / 255));
        const finalG = Math.min(255, Math.floor(lum * schemeRgb.g / 255));
        const finalB = Math.min(255, Math.floor(lum * schemeRgb.b / 255));

