"use strict";

// LevelInfoManager members, continued from core.js (kept under ~500 lines per file).
extendClass(LevelInfoManager, {
    renderBody() {
        if (!this.body) return;
        const d = this.levelData;
        const obj = this.getObjectiveBits();
        const daily = this.getDailyBits();
        const weaponId = (typeof bulletManager !== 'undefined' && bulletManager.currentWeapon)
            ? bulletManager.currentWeapon
            : (d.currentWeapon || 'laser');
        const nameOf = (id) => ((typeof iconRenderer !== 'undefined' && iconRenderer.weaponIconInfo)
            ? iconRenderer.weaponIconInfo(id).name
            : String(id).toUpperCase());
        // Every weapon fitted in the hangar, not just the one currently selected.
        const sm = typeof bulletManager !== 'undefined' ? bulletManager.currentShipModel : null;
        const fitted = (sm && sm.loadout && Array.isArray(sm.loadout.weapons) && sm.loadout.weapons.length)
            ? sm.loadout.weapons.filter((w, i, a) => w && a.indexOf(w) === i)
            : [weaponId];
        const weaponName = fitted.map(nameOf).join(' · ');

        const session = this.clusterHtml('SESSION',
            `<div class="gi-metrics gi-metrics-session">` +
            this.metricHtml('SCORE', String(this.stats.score), 'currentScore', 'navTrophy') +
            this.metricHtml('TIME', this._timeString, 'levelTime', 'navClock') +
            this.metricHtml('KILLS', String(this.stats.enemiesKilled), 'enemiesKilled', 'navSkull') +
            `</div>`,
            'gi-cluster-session'
        );

        // Loadout lives in the right rail (top).
        const loadout = this.clusterHtml('LOADOUT',
            this.rowHtml('menuEnemies', 'ENEMY', String(d.enemyType || '—').toUpperCase(), 'enemyType') +
            this.rowHtml('hsShip', 'SHIP', String(d.playerShipType || '—'), 'playerShipType') +
            this.weaponRowHtml(weaponId, 'WEAPON', weaponName, 'giCurrentWeapon'),
            'gi-cluster-loadout'
        );

        // Mission: text title + one clear card (target icon, goal, status).
        const o = typeof objectiveManager !== 'undefined' ? objectiveManager.getObjective() : null;
        const missionLabel = obj.label.replace(/:$/, '');
        const missionProgress = String(obj.progress).toUpperCase();
        const huntTarget = o && o.type === 'hunt' && o.targetEnemyId && objectiveManager.enemies
            ? objectiveManager.enemies.find((e) => e && e.id === o.targetEnemyId)
            : null;
        const missionIcon = (o && o.type === 'killCount' && o.enemyType)
            ? this.enemyIconHtml(o.enemyType, missionLabel)
            : (huntTarget
                ? this.enemyIconHtml(huntTarget.type, missionLabel)
                : this.iconHtml('menuEnemies', 28, missionLabel));
        const objCard = this.missionCardHtml(missionIcon, missionLabel, missionProgress, 'objectiveHudValue');
        const dailyRow = daily.active
            ? this.countRowHtml(this.enemyIconHtml(daily.enemyType, 'DAILY ' + daily.enemyType), 'DAILY', daily.progress, 'dailyHudValue')
            : '';
        const mission = this.clusterHtml('MISSION', objCard + dailyRow, 'gi-cluster-mission');

        // Player ship stats; anything an upgrade improves lights up.
        const stats = this.trackPlayerStats();
        const combat = this.clusterHtml('SHIP',
            `<div class="gi-metrics gi-metrics-2x2">` +
            stats.map((st) => this.statMetricHtml(st)).join('') +
            `</div>`,
            'gi-cluster-combat'
        );

        // Field loot: same 1-row metric tiles as SHIP.
        const resources = d.resources || [];
        const field = this.clusterHtml('FIELD',
            `<div class="gi-metrics gi-metrics-2x2 gi-metrics-loot">` +
            resources.map((r) => this.lootChipHtml(r)).join('') +
            `</div>`,
            'gi-cluster-field'
        );

        this.body.innerHTML = session;
        if (this.loadoutSide) {
            this.loadoutSide.innerHTML = loadout;
            this.loadoutSide.hidden = false;
        }
        if (this.under) {
            this.under.innerHTML = combat + field;
            this.under.hidden = false;
        }
        if (this.missionSide) {
            this.missionSide.innerHTML = mission;
            this.missionSide.hidden = false;
        }
    },
});


/* --- js/ui/level-info-manager/update-element.js?v=field-2 --- */
"use strict";

// LevelInfoManager methods, split from level-info-manager.js.
extendClass(LevelInfoManager, {
    updateElement(id, value) {
        const element = document.getElementById(id);
        if (element) {
            element.textContent = value;
        }
    },

    updateStats(stats) {
        this.stats = { ...this.stats, ...stats };
        this.updateElement('currentScore', this.stats.score);
        this.updateElement('enemiesKilled', this.stats.enemiesKilled);
    },

    startLevel() {
        this.stats.startTime = Date.now();
        this.stats.levelTime = 0;
        this._timeString = '00:00';
        this.prepareForCombat();
        this.updateElement('levelTime', this._timeString);
    },

    endLevel() {
        this.stopUpdateLoop();
        // Keep the panel mounted during game-over / transition so the next
        // mission start does not flash an empty vitals-only HUD.
    },

    startUpdateLoop() {
        this.stopUpdateLoop();
        this.updateInterval = setInterval(() => {
            if (typeof game !== 'undefined' && typeof game.score === 'number') {
                this.stats.score = game.score;
                this.updateElement('currentScore', this.stats.score);
            }
            if (this.stats.startTime) {
                this.stats.levelTime = Math.floor((Date.now() - this.stats.startTime) / 1000);
                const minutes = Math.floor(this.stats.levelTime / 60);
                const seconds = this.stats.levelTime % 60;
                this._timeString = `${minutes.toString().padStart(2, '0')}:${seconds.toString().padStart(2, '0')}`;
                this.updateElement('levelTime', this._timeString);
            }
            if (typeof objectiveManager !== 'undefined') {
                this.updateTransitMap();
            }
            if (typeof objectiveManager !== 'undefined' || typeof dailyTracker !== 'undefined') {
                const objVal = document.getElementById('objectiveHudValue');
                const dailyVal = document.getElementById('dailyHudValue');
                if (objVal) {
                    const obj = this.getObjectiveBits();
                    const next = String(obj.progress).toUpperCase();
                    if (objVal.textContent !== next) objVal.textContent = next;
                }
                if (dailyVal) {
                    const daily = this.getDailyBits();
                    const next = daily.active ? daily.progress : '—';
                    if (dailyVal.textContent !== next) dailyVal.textContent = next;
                }
                // Only refresh loot chips when the bag actually changed — a full
                // updateDisplay()/renderBody() every second rebuilt the whole GI panel.
                if (this.levelData) {
                    const resources = this.collectRunResources();
                    const sig = (resources || []).map((r) => r.id + ':' + r.amount).join('|');
                    if (sig !== this._resourceSig) {
                        this._resourceSig = sig;
                        this.levelData.resources = resources;
                        this.updateDisplay();
                    }
                }
            }
        }, 1000);
    },

    stopUpdateLoop() {
        if (this.updateInterval) {
            clearInterval(this.updateInterval);
            this.updateInterval = null;
        }
    },

    collectPlanetObstacles(planetId) {
        if (typeof planetConfigManager === 'undefined' || !planetId) return [];
        const cfg = planetConfigManager.getConfig(planetId);
        if (!cfg) return [];
        const types = (Array.isArray(cfg.obstacles) && cfg.obstacles.length)
            ? cfg.obstacles.map((o) => (o && (o.type || o.id)) || o)
            : (cfg.obstacleTypes || []);
        // One chip per obstacle kind (small/medium asteroid -> ASTEROID);
        // the sizes go into the chip tooltip.
        const kinds = {};
        const order = [];
        types.forEach((t) => {
            if (!t) return;
            const parts = String(t).toLowerCase().split('_');
            const kind = parts[parts.length - 1];
            const size = parts.slice(0, -1).join(' ');
            if (!kinds[kind]) { kinds[kind] = []; order.push(kind); }
            if (size && kinds[kind].indexOf(size) === -1) kinds[kind].push(size);
        });
        return order.map((kind) => ({
            name: kind.charAt(0).toUpperCase() + kind.slice(1),
            sizes: kinds[kind]
        }));
    },

    collectEquippedWeapons() {
        if (typeof shipLoadoutManager === 'undefined' || typeof profileManager === 'undefined'
            || !profileManager.getActiveShipId) return [];
        const ids = (shipLoadoutManager.getLoadout(profileManager.getActiveShipId()).weapons || []);
        const seen = {};
        return ids.filter((id) => id && !seen[id] && (seen[id] = true)).map((id) => {
            const w = typeof weaponConfigManager !== 'undefined' ? weaponConfigManager.getWeapon(id) : null;
            return { name: (w && w.name) || id, id: id, count: ids.filter((x) => x === id).length };
        });
    },

    collectRunResources() {
        const bag = (typeof pickupManager !== 'undefined' && pickupManager.collectedThisRun)
            ? pickupManager.collectedThisRun
            : {};
        const ids = (typeof economyConfig !== 'undefined' && economyConfig.resourceIds)
            ? economyConfig.resourceIds
            : Object.keys(bag);
        return ids.map((id) => ({
            id: id,
            name: (typeof economyConfig !== 'undefined' && economyConfig.getResourceLabel)
                ? economyConfig.getResourceLabel(id)
                : String(id).toUpperCase(),
            amount: Number(bag[id]) || 0
        }));
    },

    collectLevelData() {
        const levelData = {
            name: 'MARS — STAGE 1/3',
            difficulty: 'EASY',
            enemyType: 'enemyBasic',
            enemySpeed: '0.8',
            enemyHealth: '100',
            enemyCount: '5',
            obstacles: [],
            obstacleSpawnRate: 1000,
            playerShipType: 'Starfighter',
            playerSpeed: '1.0',
            playerMaxHealth: '100',
            currentWeapon: 'Laser',
            weapons: [],
            resources: []
        };

        const coreLM = (typeof game !== 'undefined' && (game.coreLevelManager || game.levelManager))
            || (typeof gameCore !== 'undefined' && (gameCore.coreLevelManager || gameCore.levelManager))
            || null;
        const current = coreLM && coreLM.getCurrentLevel ? coreLM.getCurrentLevel() : null;
        if (current) {
            levelData.name = current.name || levelData.name;
            levelData.difficulty = current.difficulty || levelData.difficulty;
            levelData.enemyType = current.enemyType || levelData.enemyType;
            levelData.enemySpeed = current.enemySpeed != null ? String(current.enemySpeed) : levelData.enemySpeed;
            levelData.enemyHealth = current.enemyHealth != null ? String(current.enemyHealth) : levelData.enemyHealth;
            levelData.enemyCount = current.enemyCount != null ? String(current.enemyCount) : levelData.enemyCount;
            levelData.obstacles = current.obstacles || levelData.obstacles;
            levelData.obstacleSpawnRate = current.obstacleSpawnRate || levelData.obstacleSpawnRate;
            levelData.stageLabel = current.stageLabel || '';
            levelData.planetName = current.planetName || levelData.planetName || '';
            levelData.isBoss = !!current.isBoss;
            levelData.planetId = current.planetId || levelData.planetId;
            levelData.objective = current.objective || null;
            if (current.weapons) levelData.weapons = current.weapons;
        }
        // FIELD shows only what this run really has: the planet's obstacle
        // types and the weapons equipped on the flying ship.
        levelData.obstacles = this.collectPlanetObstacles(levelData.planetId);
        levelData.weapons = this.collectEquippedWeapons();
        levelData.resources = this.collectRunResources();

        if (typeof enemyManager !== 'undefined' && enemyManager.getEnemy()) {
            const enemy = enemyManager.getEnemy();
            levelData.enemySpeed = enemy.speed?.toFixed(1) || levelData.enemySpeed;
            levelData.enemyHealth = enemyManager.maxHealth || levelData.enemyHealth;
        }

        if (typeof playerManager !== 'undefined') {
            levelData.playerSpeed = playerManager.player?.speed?.toFixed(1) || '1.0';
            levelData.playerMaxHealth = playerManager.maxHealth || '100';
        }

        if (typeof obstacleManager !== 'undefined') {
            levelData.obstacleSpawnRate = obstacleManager.spawnInterval || levelData.obstacleSpawnRate;
        }

        if (typeof game !== 'undefined' && game.gameState) {
            levelData.obstacleSpawnRate = game.gameState.obstacleSpawnInterval || levelData.obstacleSpawnRate;
        }

        if (typeof graphicsManager !== 'undefined' && graphicsManager.currentPlayerModel) {
            levelData.playerShipType = graphicsManager.currentPlayerModel.name || 'Starfighter';
        }

        if (typeof game !== 'undefined' && game.currentWeaponName) {
            levelData.currentWeapon = game.currentWeaponName;
        } else {
            const weaponLabel = document.querySelector('.weapon-display #currentWeapon');
            if (weaponLabel && weaponLabel.textContent) {
                levelData.currentWeapon = weaponLabel.textContent.trim();
            }
        }

        return levelData;
    },

    showLootNotice(text) {
        const msg = String(text || '').trim();
        if (!msg) return;
        let el = document.getElementById('vfLootNotice');
        if (!el) {
            el = document.createElement('div');
            el.id = 'vfLootNotice';
            el.style.cssText = [
                'position:fixed',
                'top:12%',
                'left:50%',
                'transform:translateX(-50%)',
                'z-index:9999',
                'padding:8px 14px',
                'background:rgba(0,0,0,0.75)',
                'color:#b8f0c0',
                'font-family:monospace',
                'font-size:var(--font-text)',
                'letter-spacing:0.04em',
                'pointer-events:none',
                'border:var(--ui-border-width) solid rgba(184,240,192,0.4)'
            ].join(';');
            document.body.appendChild(el);
        }
        el.textContent = msg;
        el.style.opacity = '1';
        clearTimeout(this._lootNoticeTimer);
        this._lootNoticeTimer = setTimeout(() => {
            if (el) el.style.opacity = '0';
        }, 2800);
    },

    showEventAnnounce(text, options) {
        const msg = String(text || '').trim();
        if (!msg) return;
        const opts = options || {};
        const accent = opts.accent || '#e8c060';
        const holdMs = Math.max(800, Math.round(Number(opts.holdMs != null ? opts.holdMs : 2200)));
        let el = document.getElementById('vfEventAnnounce');
        if (!el) {
            el = document.createElement('div');
            el.id = 'vfEventAnnounce';
            el.className = 'vf-event-announce';
            document.body.appendChild(el);
        }
        el.textContent = msg;
        el.style.borderColor = accent;
        el.style.color = accent;
        el.style.opacity = '1';
        el.classList.add('vf-event-announce-pulse');
        clearTimeout(this._eventAnnounceTimer);
        this._eventAnnounceTimer = setTimeout(() => {
            if (el) {
                el.style.opacity = '0';
                el.classList.remove('vf-event-announce-pulse');
            }
        }, holdMs);
        // Transit rail: pop the matching contact icon as soon as the event is announced.
        if (this.revealTransitEvent) {
            this.revealTransitEvent({
                id: opts.id || opts.eventId || null,
                role: opts.role || opts.catalogId || null,
                type: opts.type || null,
                accent: accent
            });
        }
    },
});


